pub(crate) fn upsert_session(
    conn: &rusqlite::Connection,
    session_id: &str,
    agent_name: &str,
    user: &str,
    created_at: &str,
    updated_at: &str,
    cwd: &str,
    session_name: &str,
) -> Result<()> {
    // agent_name is preserved on update if the existing row already has one —
    // shadow branches don't carry a reliable agent identifier, so we don't want
    // a shadow upsert to clobber an agent_name that the checkpoint scan or the
    // session-start hook already set authoritatively.
    conn.execute(
        "INSERT INTO sessions (session_id, agent_name, user, created_at, updated_at, cwd, session_name)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)
         ON CONFLICT(session_id) DO UPDATE SET
           agent_name   = CASE WHEN COALESCE(sessions.agent_name, '') = ''
                               THEN excluded.agent_name
                               ELSE sessions.agent_name END,
           updated_at   = MAX(sessions.updated_at, excluded.updated_at),
           cwd          = CASE WHEN excluded.cwd != '' THEN excluded.cwd ELSE sessions.cwd END,
           session_name = excluded.session_name",
        rusqlite::params![session_id, agent_name, user, created_at, updated_at, cwd, session_name],
    )?;
    Ok(())
}

