                if let Some(t) = v["customTitle"].as_str() { out.session_name = t.to_string(); }
            }
            Some("user") | Some("system") => {
                if out.cwd.is_empty() {
                    if let Some(c) = v["cwd"].as_str() { out.cwd = c.to_string(); }
                }
            }
