        }
        if v["type"].as_str() == Some("user") {
            if let Some(t) = user_text(&v["message"]["content"]) {
                last_prompt = t;
            }
        }
        if let Some(b) = v["gitBranch"].as_str() {
            if !b.is_empty() { out.branch = b.to_string(); }
        }
    }
    if out.session_name.is_empty() { out.session_name = last_prompt; }
    out
